let data, trello = {items:{}}, content={entries:[]}, mastery={levels:[],summary:{}}, syncMeta=null, sourceAudit=null, page = 'home', query = '', filters = {}, selected = [], trade = { yours: [], theirs: [] }, tradeHistory=[], recentItems=[], ideaTarget='';
const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const get = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const put = (key, value) => localStorage.setItem(key, JSON.stringify(value));
tradeHistory=get('haze-trade-history',[]);
recentItems=get('haze-recent-items',[]);
let favorites = get('haze-favorites', []), settings = get('haze-settings', { theme: 'dark', density: 'comfortable', sidebar: false }), eventClockTimer = null;
const money = n => n == null ? 'Unlisted' : new Intl.NumberFormat().format(n);
const esc = s => String(s ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const title = s => s.replace(/\b\w/g, x => x.toUpperCase());
function updateStormClock(){const counter=$('#eventCountdown'),label=$('#eventCountdownLabel'),badge=$('#eventStatus'),api=window.hazeEventTimer;if(!counter||!label||!badge||!api)return;const state=api.eventState(api.readSettings(localStorage),Date.now());if(!state){counter.textContent='--:--:--';label.textContent='Enter the current server time to calculate a schedule.';badge.textContent='NEXT WINDOW';badge.className='pill stable';return}counter.textContent=api.formatDuration(state.remainingMs);label.textContent=state.active?'Window closes in':'Storm begins in';badge.textContent=state.active?'ACTIVE WINDOW':'NEXT WINDOW';badge.className=`pill ${state.active?'high':'stable'}`;}
function setupStormClock(){if(eventClockTimer){clearInterval(eventClockTimer);eventClockTimer=null}if(page!=='timers')return;updateStormClock();eventClockTimer=setInterval(updateStormClock,1000);}
function rememberItem(item){const snapshot={id:item.id,name:item.name,value:item.value,valueText:item.valueText||'Unlisted',demand:item.demand||'—',seenAt:new Date().toISOString()},latest=recentItems.find(x=>x.id===item.id);if(latest&&latest.value===snapshot.value&&latest.demand===snapshot.demand)return;recentItems=[snapshot,...recentItems].slice(0,40);put('haze-recent-items',recentItems);}
function nearbyItems(item){if(!Number.isFinite(Number(item.value))||item.value<=0)return [];return data.items.filter(x=>x.id!==item.id&&Number.isFinite(Number(x.value))&&x.value>0).map(x=>({...x,diff:((x.value-item.value)/item.value)*100})).filter(x=>Math.abs(x.diff)<=20).sort((a,b)=>Math.abs(a.diff)-Math.abs(b.diff)).slice(0,4);}
function openIdeas(id){ideaTarget=id;page='ideas';const dialog=$('#detailDialog');if(dialog?.open)dialog.close();render();}
function toast(message) { const e = $('#toast'); e.textContent = message; e.classList.add('show'); setTimeout(() => e.classList.remove('show'), 2600); }
function saveFavorites() { put('haze-favorites', favorites); $('#favCount').textContent = favorites.length || ''; }
function isFav(id) { return favorites.some(x => x.id === id); }
function toggleFav(id) { const found = data.items.find(x => x.id === id); if (!found) return; const adding = !isFav(id); favorites = adding ? [...favorites, { ...found, note: '', date: new Date().toISOString() }] : favorites.filter(x => x.id !== id); saveFavorites(); render(); toast(adding ? 'Added to favorites' : 'Removed from favorites'); }
function normalizedItems(items=[]){const demand=/^(low|medium|mid|high|very high|extreme|stable|unknown|n\/?a|—)$/i,map=new Map();for(const raw of items){const item={...raw},numeric=String(item.valueText||'').replace(/,/g,'').match(/^\d+(?:\.\d+)?$/);if(item.value==null&&numeric)item.value=Number(numeric[0]);const score=(Number.isFinite(item.value)?4:0)+(numeric?3:0)+(demand.test(String(item.demand||''))?3:0)+(item.rarity?1:0),previous=map.get(item.id);if(!previous||score>previous._quality)map.set(item.id,{...item,_quality:score})}return [...map.values()].map(({_quality,...item})=>item)}
function filteredItems(category) { const unique=normalizedItems(data.items);return unique.filter(x => {
 const q = query.toLowerCase(); const matches = !q || [x.name,x.category,x.rarity,x.demand,x.valueText,x.pvp,x.pve].join(' ').toLowerCase().includes(q);
 return matches && (!category || x.category.toLowerCase() === category) && (!filters.rarity || x.rarity === filters.rarity) && (!filters.demand || x.demand === filters.demand) && (!filters.min || x.value >= Number(filters.min)) && (!filters.max || x.value <= Number(filters.max)) && (!filters.favorites || isFav(x.id));
 }); }
function status(item) { const demand = String(item.demand || '').toLowerCase(); if (demand.includes('high') || demand.includes('extreme')) return '<span class="pill high">High Demand</span>'; if (item.value == null || item.valueText === '???' || item.valueText === 'Unlisted') return '<span class="pill muted">Unlisted</span>'; if (demand.includes('low')) return '<span class="pill muted">Low Demand</span>'; return '<span class="pill stable">Stable</span>'; }
function cleanDisplayName(s=''){return String(s).replace(/[\u1cbc\u200b\u200c\u200d\ufeff]/g,'').trim();}
function accessoryKey(s=''){return String(s).toLowerCase().replace(/neptune'?s?/g,'neptune').replace(/seabeast|sea beast/g,'seabeast').replace(/[^a-z0-9]/g,'')}
const verifiedPngArtwork=new Set(['accessories-gpm','accessories-abyssal-necklace','accessories-dominus-messor','accessories-gravity-gauntlet','accessories-emperor-cape','accessories-sb-helmet-v2','accessories-drums','accessories-pumpkin-mask','swords-gryphon','misc-items-broom','gamepasses-2x-money','gamepasses-increase-drop-rate','gamepasses-fruit-bag','gamepasses-striker-boat','gamepasses-custom-armament-color','perm-fruits-robux-saturn']);
const artPath=item=>`item-thumbnails/${item.id}${verifiedPngArtwork.has(item.id)?'.png':'.webp'}`;
function art(item){return `<img class="item-art" src="./${esc(artPath(item))}" loading="lazy" decoding="async" width="360" height="270" alt="Verified Haze Seas art for ${esc(item.name)}">`;}

function accessoryStatRows(){const source=content.entries.find(x=>x.category==='Accessories'&&x.name==='Accessory Info'),rows=[];if(!source)return rows;let rarity='';for(const raw of source.description.split('\n')){const line=raw.replace(/[‌﻿`]/g,'').trim(),heading=line.match(/^\*\*(.+?)\*\*/);if(heading){rarity=heading[1].toUpperCase();continue}const match=line.match(/^[-*]\s*(.+?)\s*=\s*(.+)$/);if(match)rows.push({name:match[1].trim(),rarity,raw:match[2].trim(),source:source.source})}return rows}
function accessoryStats(item){if(item.category!=='Accessories')return null;const aliases={gpm:'goldenpumpkinmask',sbhelmetv2:'seabeasthelmetv2',seabeasthelmet:'seabeasthelmetv2',seabeastarmor:'seabeastarmorv1',gravitygauntlet:'gravitygauntlets',drums:'drums',eyepatch:'eyepatch'},wanted=aliases[accessoryKey(item.name)]||accessoryKey(item.name),matches=accessoryStatRows().filter(x=>accessoryKey(x.name)===wanted);const row=matches.find(x=>x.rarity===String(item.rarity||'').toUpperCase())||matches[0];if(!row)return {stats:[],source:null};const stats=row.raw.split(/,\s*|\s+(?=\+\s*\d+(?:\.\d+)?(?:%|\s+[A-Za-z]))/).map(x=>x.trim()).filter(Boolean);return {stats,source:row.source}}
function accessoryStatsInline(item){const info=accessoryStats(item);if(!info?.stats.length)return '';return `<div class="accessory-stat-preview">${info.stats.slice(0,3).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`}
function accessoryStatsPanel(item){const info=accessoryStats(item);if(!info)return '';return `<section class="panel accessory-stats"><div class="panel-title"><h2>Accessory stats</h2><span>Official Trello</span></div>${info.stats.length?`<div class="accessory-stat-grid">${info.stats.map(x=>`<div><small>STAT BONUS</small><strong>${esc(x)}</strong></div>`).join('')}</div>`:'<p class="muted">No stat bonuses are documented for this accessory in the current official Accessory Info card.</p>'}${info.source?`<a class="secondary guide-source" href="${esc(info.source)}" target="_blank" rel="noopener">View official Accessory Info</a>`:''}</section>`}
function card(item) { return `<article class="item-card" data-item="${esc(item.id)}" role="button" tabindex="0" aria-label="Open ${esc(item.name)} details"><div class="card-top">${art(item)}<button type="button" class="favorite ${isFav(item.id)?'on':''}" data-fav="${esc(item.id)}" aria-label="${isFav(item.id)?'Remove from':'Add to'} favorites">♥</button></div><h3>${esc(item.name)}</h3><p>${esc(item.category)} · ${esc(item.rarity || 'Unknown')}</p>${accessoryStatsInline(item)}<div class="card-value">${esc(item.valueText || 'Unlisted')}</div><div class="card-bottom">${status(item)}<span>${esc(item.demand || '—')}</span></div></article>`; }
function stat(label, value, icon, tint='') { return `<div class="stat ${tint}"><div><small>${label}</small><strong>${value}</strong></div><span>${icon}</span></div>`; }
function home() { const listed = data.items.filter(x=>x.value!=null); const top = [...listed].sort((a,b)=>b.value-a.value).slice(0,5); return `<div class="page-head"><div><p class="eyebrow">TRADING INTELLIGENCE</p><h1>Welcome aboard, trader.</h1><p class="muted">Current values, demand and game knowledge—organized for fast decisions.</p></div><button class="primary" onclick="go('items')">Browse all values →</button></div><div class="stats">${stat('TRACKED ITEMS',data.items.length,'◈')}${stat('FRUITS',data.items.filter(x=>x.category==='Fruits').length,'◉','cyan')}${stat('ACCESSORIES',data.items.filter(x=>x.category==='Accessories').length,'♛','gold')}${stat('FAVORITES',favorites.length,'♥','pink')}</div><div class="dashboard-grid"><section class="panel top-values"><div class="panel-title"><h2>Most valuable</h2><button onclick="go('items')">View database →</button></div><div class="rank-list">${top.map((x,i)=>`<button data-item="${x.id}"><b>#${i+1}</b><span>${esc(x.name)}<small>${esc(x.category)} · ${esc(x.rarity)}</small></span><strong>${esc(x.valueText)}</strong></button>`).join('')}</div></section><section class="panel why"><p class="eyebrow">HOW IT WORKS</p><h2>Trade with clarity.</h2><p>Values come from the published Haze Seas Value List. Use demand and rarity alongside value—then compare both offers before accepting.</p><button class="secondary" onclick="go('tutorial')">Read the trading guide</button></section></div><section class="panel"><div class="panel-title"><h2>Quick browse</h2><span>Explore item classes</span></div><div class="quick-cats">${['Fruits','Accessories','Swords','Misc Items','Gamepasses'].map((x,i)=>`<button onclick="go('${x.toLowerCase()}')"><i>${['◉','♛','⚔','◈','◇'][i]}</i><span>${x}</span><small>${data.items.filter(y=>y.category===x).length} items</small></button>`).join('')}</div></section>`; }
function quickTools(){const codeCount=typeof parseOfficialCodes==='function'?parseOfficialCodes().length:0;return `<section class="panel quick-tools"><div class="panel-title"><h2>Quick tools</h2><span>Most-used actions</span></div><div class="quick-cats"><button onclick="go('trade')"><i>⇄</i><span>Trade calculator</span><small>Check an offer</small></button><button onclick="go('mastery')"><i>✧</i><span>Mastery XP</span><small>Plan progression</small></button><button onclick="go('codes')"><i>#</i><span>Codes</span><small>${codeCount||'Official'} redeemables</small></button><button onclick="go('timers')"><i>☠</i><span>Boss timers</span><small>Spawns & events</small></button><button onclick="go('systems')"><i>⚙</i><span>Game systems</span><small>Mastery, materials…</small></button><button onclick="go('tutorial')"><i>?</i><span>Trading guide</span><small>Learn the basics</small></button></div></section>`;}
function filtersUI() { const options = (field) => [...new Set(data.items.map(x=>x[field]).filter(Boolean))].sort().map(x=>`<option value="${esc(x)}" ${filters[field]===x?'selected':''}>${esc(x)}</option>`).join(''); return `<details class="filter-panel"><summary>☷ Filters <span>${Object.keys(filters).length?'• Active':''}</span></summary><div><label>Rarity<select data-filter="rarity"><option value="">Any rarity</option>${options('rarity')}</select></label><label>Demand<select data-filter="demand"><option value="">Any demand</option>${options('demand')}</select></label><label>Min value<input type="number" data-filter="min" value="${filters.min||''}" placeholder="0"></label><label>Max value<input type="number" data-filter="max" value="${filters.max||''}" placeholder="No max"></label><label class="check"><input type="checkbox" data-filter="favorites" ${filters.favorites?'checked':''}> Favorites only</label><button onclick="filters={};render()">Reset filters</button></div></details>`; }
function itemsPage(category) { const items = filteredItems(category); return `<div class="page-head compact"><div><p class="eyebrow">VALUE DATABASE</p><h1>${category ? title(category) : 'All items'}</h1><p class="muted">${items.length} matching items · click an item for details</p></div><div class="view-switch"><button class="active">▦ Grid</button><button onclick="tablePage('${category||''}')">☷ Table</button></div></div>${filtersUI()}<div class="item-grid">${items.map(card).join('') || '<div class="empty">No items match those filters. Try clearing them.</div>'}</div>`; }
function miscItemsPage(){const listed=filteredItems('misc items'),official=content.entries.filter(x=>!x.aliasOf&&!x.archived&&x.category==='Misc Items');return `<div class="page-head compact"><div><p class="eyebrow">MATERIALS & OTHER</p><h1>Miscellaneous Items</h1><p class="muted">${listed.length} value-listed item${listed.length===1?'':'s'} · ${official.length} official Trello records</p></div></div><section class="panel misc-value-panel"><div class="panel-title"><h2>Trading Values</h2><span class="muted">Value List</span></div><div class="item-grid">${listed.map(card).join('')||'<div class="empty">No Miscellaneous item values are currently listed.</div>'}</div></section><section class="panel misc-official-panel"><div class="panel-title"><h2>Official Miscellaneous Items</h2><span class="muted">Trello</span></div><p class="muted">Gameplay records, requirements, and official item images. Click an item for its full details.</p><div class="item-grid">${official.map(x=>`<article class="item-card content-card ${x.released?'':'unreleased'}" data-content="${esc(x.id)}"><div class="card-top">${contentArt(x)}<span class="pill muted">${x.released?'GAMEPLAY':'🚧 UNRELEASED'}</span></div><h3>${esc(x.name)}</h3><div class="card-bottom"><span>Official Trello</span></div></article>`).join('')}</div></section>`;}
function tablePage(category='') { const items=filteredItems(category).sort((a,b)=>(b.value||0)-(a.value||0)); $('#view').innerHTML=`<div class="page-head compact"><div><p class="eyebrow">VALUE DATABASE</p><h1>${category?title(category):'All items'} table</h1><p class="muted">Sort-ready, complete spreadsheet data</p></div><div class="view-switch"><button onclick="go('${category||'items'}')">▦ Grid</button><button class="active">☷ Table</button></div></div>${filtersUI()}<div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Value</th><th>Demand</th><th>Rarity</th><th>PvP</th><th>PvE</th><th>Status</th></tr></thead><tbody>${items.map(x=>`<tr data-item="${x.id}"><td><b>${esc(x.name)}</b></td><td>${esc(x.category)}</td><td class="gold-text">${esc(x.valueText||'Unlisted')}</td><td>${esc(x.demand||'—')}</td><td>${esc(x.rarity||'—')}</td><td>${esc(x.pvp||'—')}</td><td>${esc(x.pve||'—')}</td><td>${status(x)}</td></tr>`).join('')}</tbody></table></div>`; bindDynamic(); }
function favoritesPage() { const items=favorites.map(x=>data.items.find(y=>y.id===x.id)||x); return `<div class="page-head compact"><div><p class="eyebrow">YOUR COLLECTION</p><h1>Favorites</h1><p class="muted">Saved locally on this PC.</p></div></div><div class="item-grid">${items.map(card).join('')||'<div class="empty">No favorites yet. Tap the heart on any item to save it here.</div>'}</div>`; }
function scheduleMarkup(groups){return groups.map(group=>`<section class="event-day"><h3>${esc(group.date)}</h3><div>${group.events.map(event=>`<time datetime="${new Date(event.timestamp).toISOString()}">${esc(event.time)}</time>`).join('')}</div></section>`).join('')||'<p class="muted">No starts fall inside this horizon.</p>';}
function serverScheduleMarkup(starts,settings){const api=window.hazeEventTimer;return `<section class="event-day"><h3>Server time</h3><div>${starts.map(timestamp=>`<time>${esc(api.formatServerElapsed(api.serverElapsedAt(settings,timestamp)))}</time>`).join('')}</div></section>`;}
function timersPage(){const api=window.hazeEventTimer,config=api?.getConfig('storm');if(!api||!config)return `<div class="empty">Event timer configuration is unavailable in this build.</div>`;const saved=api.readSettings(localStorage),now=Date.now(),state=api.eventState(saved,now),serverElapsed=saved?api.formatServerElapsed(api.serverElapsedAt(saved,now)):'',starts=hours=>state?api.upcomingStarts(saved,now,hours*60*60*1000):[];return `<div class="page-head compact"><div><p class="eyebrow">VERIFIED EVENT TRACKER</p><h1>Storm timer</h1><p class="muted">Storm starts at 2:35 server time, lasts 10 minutes, then resets for 2h 35m. Enter the current server time once; this device keeps it moving.</p></div></div><section class="panel event-hero"><div><span id="eventStatus" class="pill ${state?.active?'high':'stable'}">${state?.active?'ACTIVE WINDOW':'NEXT WINDOW'}</span><h2 id="eventCountdown" aria-live="polite">${state?api.formatDuration(state.remainingMs):'--:--:--'}</h2><p id="eventCountdownLabel">${state?(state.active?'Window closes in':'Storm begins in'):'Enter the current server time to calculate a schedule.'}</p></div><dl><div><dt>After Storm ends</dt><dd>2h 35m</dd></div><div><dt>Start-to-start cycle</dt><dd>2h 45m</dd></div><div><dt>Window</dt><dd>10 minutes</dd></div><div><dt>Source</dt><dd><a href="${config.sourceUrl}" target="_blank" rel="noopener">Official Trello ↗</a></dd></div></dl></section><section class="panel event-anchor"><div class="panel-title"><div><h2>Current server time</h2><span>Saved only in this browser · no timezone needed</span></div></div><div class="event-anchor-controls"><label>Server elapsed time (H:MM)<input id="eventServerElapsed" type="text" inputmode="numeric" pattern="[0-9]{1,4}:[0-5][0-9]" placeholder="2:35" value="${esc(serverElapsed)}"></label><button class="primary" id="eventServerElapsedSave">Save server time</button>${saved?'<button class="secondary" id="eventAnchorClear">Clear</button>':''}</div><p class="detail-note">Enter the server's current elapsed time, such as 2:35. The first Storm starts at 2:35; this browser then keeps that server clock moving.</p></section><div class="event-schedules">${state?`<section class="panel"><div class="panel-title"><h2>Next 10 server hours</h2><span>${starts(10).length} starts</span></div>${serverScheduleMarkup(starts(10),saved)}</section><section class="panel"><div class="panel-title"><h2>Next 50 server hours</h2><span>${starts(50).length} starts</span></div>${serverScheduleMarkup(starts(50),saved)}</section>`:'<section class="panel"><h2>Schedule unavailable</h2><p class="muted">Enter the current server elapsed time above to calculate this server Storm schedule.</p></section>'}</div><section class="panel event-notifications"><h2>Notifications</h2><p class="muted">Notification delivery is intentionally not implemented. The timer exposes a future adapter boundary, but it does not request permission or schedule alerts.</p></section>`;}
function tradeIdeasPage(){const values=data.items.filter(x=>Number.isFinite(Number(x.value))&&x.value>0),target=values.find(x=>x.id===ideaTarget)||values[0];if(target)ideaTarget=target.id;const matches=target?values.filter(x=>x.id!==target.id).map(item=>({item,difference:item.value-target.value,percent:((item.value-target.value)/target.value)*100})).filter(x=>Math.abs(x.percent)<=20).sort((a,b)=>Math.abs(a.difference)-Math.abs(b.difference)).slice(0,12):[];return `<div class="page-head compact"><div><p class="eyebrow">TRADE GUIDE</p><h1>What can I trade for?</h1><p class="muted">Nearby current values only—use demand and item condition before accepting a deal.</p></div></div><section class="panel settings"><label>Pick an item<select id="ideaTarget">${values.map(x=>`<option value="${esc(x.id)}" ${x.id===ideaTarget?'selected':''}>${esc(x.name)} · ${esc(x.valueText)}</option>`).join('')}</select></label></section><div class="panel-title"><h2>Within 20% of ${esc(target?.name||'your item')}</h2><span>${matches.length} ideas</span></div><div class="item-grid">${matches.map(x=>`<article class="item-card" data-item="${esc(x.item.id)}"><div class="card-top">${art(x.item)}<span class="pill">${x.percent>=0?'+':''}${x.percent.toFixed(1)}%</span></div><h3>${esc(x.item.name)}</h3><div class="card-bottom"><b>${esc(x.item.valueText)}</b><span>${esc(x.item.demand||'—')}</span></div></article>`).join('')||'<div class="empty">No nearby listed values for this item.</div>'}</div>`;}
function historyPage(){return `<div class="page-head compact"><div><p class="eyebrow">SAVED LOCALLY</p><h1>Trade history</h1><p class="muted">Your last 20 saved checks on this device.</p></div><button class="secondary" id="clearTradeHistory">Clear history</button></div><div class="content-groups">${tradeHistory.map(h=>`<section class="panel"><div class="panel-title"><h2>${esc(h.result||'Trade check')}</h2><span>${new Date(h.savedAt).toLocaleString()}</span></div><p><b>You:</b> ${esc((h.yours||[]).join(', ')||'None')}<br><b>Them:</b> ${esc((h.theirs||[]).join(', ')||'None')}</p><strong>${esc(h.differenceText||'—')} · ${esc(h.percentageText||'—')}</strong></section>`).join('')||'<div class="empty">Save a completed calculation to keep it here.</div>'}</div>`;}
function saveTradeHistory(){if(!trade.yours.length&&!trade.theirs.length)return toast('Add at least one item first');const r=window.valueEngine?.calculateTrade?window.valueEngine.calculateTrade(trade.yours,trade.theirs):calc();tradeHistory=[{id:`trade-${Date.now()}`,savedAt:new Date().toISOString(),yours:trade.yours.map(x=>x.name),theirs:trade.theirs.map(x=>x.name),result:r.result,differenceText:`${r.difference>=0?'+':''}${money(r.difference)}`,percentageText:`${r.percentage>=0?'+':''}${r.percentage}%`},...tradeHistory].slice(0,20);put('haze-trade-history',tradeHistory);toast('Trade check saved');}
function comparePage() { const picks=selected.map(id=>data.items.find(x=>x.id===id)).filter(Boolean); return `<div class="page-head compact"><div><p class="eyebrow">SIDE BY SIDE</p><h1>Compare items</h1><p class="muted">Select 2–5 items to identify the strongest trade assets.</p></div><button class="secondary" onclick="selected=[];render()">Remove all</button></div><div class="compare-picker">${data.items.map(x=>`<button class="${selected.includes(x.id)?'selected':''}" data-compare="${x.id}">${selected.includes(x.id)?'✓ ':''}${esc(x.name)}</button>`).join('')}</div>${picks.length?`<div class="compare-grid">${picks.map(x=>`<section class="compare-card"><button class="close" data-compare="${x.id}">×</button>${art(x)}<h2>${esc(x.name)}</h2><p>${esc(x.category)}</p><dl><div><dt>Value</dt><dd>${esc(x.valueText||'Unlisted')}</dd></div><div><dt>Demand</dt><dd>${esc(x.demand||'—')}</dd></div><div><dt>Rarity</dt><dd>${esc(x.rarity||'—')}</dd></div><div><dt>PvP / PvE</dt><dd>${esc(x.pvp||'—')} / ${esc(x.pve||'—')}</dd></div></dl><button class="secondary" data-add-trade="${x.id}">Add to my offer</button></section>`).join('')}</div>`:'<div class="empty">Choose up to five items above to compare their data.</div>'}`; }
function tradePage() { const side=(name,list)=>`<section class="offer"><h2>${name}</h2><div class="offer-list">${list.map(x=>`<div><span>${esc(x.name)}</span><b>${esc(x.valueText||'Unlisted')}</b><button data-remove="${name==='Your offer'?'yours':'theirs'}:${x.id}">×</button></div>`).join('')||'<p class="muted">No items added</p>'}</div><button class="secondary" data-pick-trade="${name==='Your offer'?'yours':'theirs'}">+ Add item</button><strong>Total <em>${money(list.reduce((s,x)=>s+(x.value||0),0))}</em></strong></section>`; const r=window.valueEngine?.calculateTrade ? window.valueEngine.calculateTrade(trade.yours,trade.theirs) : calc(); return `<div class="page-head compact"><div><p class="eyebrow">NEGOTIATION TOOL</p><h1>Trade calculator</h1><p class="muted">Only listed values are counted. Unlisted items count as 0.</p></div><button class="secondary" onclick="trade={yours:[],theirs:[]};render()">Reset trade</button></div><div class="trade-grid">${side('Your offer',trade.yours)}<section class="trade-result"><p>VALUE DIFFERENCE</p><strong class="${r.difference>=0?'win':'loss'}">${r.difference>=0?'+':''}${money(r.difference)}</strong><h2>${r.result}</h2><span>${r.percentage>=0?'+':''}${r.percentage}% for your side</span><button class="primary" onclick="const x=trade.yours;trade.yours=trade.theirs;trade.theirs=x;render()">⇄ Swap offers</button><button class="secondary" data-save-trade>Save this check</button></section>${side('Their offer',trade.theirs)}</div>`; }
function openTradePicker(side){const dialog=$('#tradePicker'), draw=q=>{const items=data.items.filter(x=>x.name.toLowerCase().includes(q.toLowerCase())).slice(0,80);$('#tradePickerContent').innerHTML=`<button class="close" id="closeTradePicker">×</button><div class="picker-head"><p class="eyebrow">${side==='yours'?'YOUR OFFER':'THEIR OFFER'}</p><h2>Choose an item</h2><p class="muted">Search and click an item to add it.</p><input id="tradePickSearch" autofocus placeholder="Search items…" value="${esc(q)}"></div><div class="trade-pick-list">${items.map(x=>`<button data-trade-choice="${esc(x.id)}">${art(x)}<span><b>${esc(x.name)}</b><small>${esc(x.category)} · ${esc(x.rarity||'Unknown')}</small></span><strong>${esc(x.valueText||'Unlisted')}</strong></button>`).join('')||'<p class="muted">No matching items.</p>'}</div>`;$('#closeTradePicker').onclick=()=>dialog.close();$('#tradePickSearch').oninput=e=>draw(e.target.value);$$('[data-trade-choice]').forEach(b=>b.onclick=()=>{const item=data.items.find(x=>x.id===b.dataset.tradeChoice);trade[side].push(item);dialog.close();render();toast(`${item.name} added`)});};draw('');dialog.showModal();}
function calc(){const t=a=>a.reduce((s,x)=>s+(x.value||0),0),a=t(trade.yours),b=t(trade.theirs),d=b-a,p=a?+(d/a*100).toFixed(2):0;return {difference:d,percentage:p,result:p>=20?'Big Win':p>=5?'Win':p>-5?'Fair':p>-20?'Small Loss':'Big Loss'};}
function dataStatusPage(){const meta=syncMeta||{},audit=sourceAudit||{},result=audit.result||{},sources=audit.sources||{},checkedAt=meta.checkedAt||audit.checkedAt||data.sync?.lastUpdated||data.updatedAt,conflicts=Array.isArray(result.conflicts)?result.conflicts:[],runUrl=meta.runUrl||audit.runUrl||data.sync?.runUrl;const checked=checkedAt?new Date(checkedAt).toLocaleString():'Not available yet';return `<div class="page-head compact"><div><p class="eyebrow">GITHUB ACTIONS SNAPSHOT</p><h1>Data status</h1><p class="muted">Published source checks for this GitHub Pages build. Reload fetches the latest committed snapshots; it does not scrape sources in your browser.</p></div><button class="primary" data-rd-refresh>↻ Reload snapshot</button></div><div class="stats"><div class="stat cyan"><div><small>VALUE ITEMS</small><strong>${esc(meta.values?.items??result.items??data.items.length)}</strong></div><span>◈</span></div><div class="stat gold"><div><small>OFFICIAL RECORDS</small><strong>${esc(meta.content?.entries??content.entries.length)}</strong></div><span>▤</span></div><div class="stat ${conflicts.length?'pink':'cyan'}"><div><small>SOURCE DIFFERENCES</small><strong>${conflicts.length}</strong></div><span>${conflicts.length?'!':'✓'}</span></div></div><section class="panel"><div class="panel-title"><h2>Last completed sync</h2><span class="pill ${audit.checkedAt?'stable':'muted'}">${audit.checkedAt?'COMMITTED':'NOT AVAILABLE'}</span></div><div class="details"><div><span>Checked</span><b>${esc(checked)}</b></div><div><span>Sync method</span><b>${esc(meta.via||audit.via||'GitHub Pages snapshot')}</b></div><div><span>Trello details</span><b>${esc(meta.trelloDetails?.items??Object.keys(trello.items||{}).length)} records</b></div></div>${runUrl?`<a class="secondary guide-source" href="${esc(runUrl)}" target="_blank" rel="noopener">Open GitHub Actions run ↗</a>`:''}</section><section class="panel"><div class="panel-title"><h2>Checked sources</h2><span class="muted">GitHub Actions</span></div><div class="official-links">${[['Google Sheet',sources.googleSheet],['Vaulted Values X',sources.vaultedValuesX]].filter(([,url])=>url).map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener"><span>${esc(label)}</span><em>↗</em></a>`).join('')||'<p class="muted">Source audit metadata will appear after the next successful scheduled sync.</p>'}</div></section><section class="panel"><div class="panel-title"><h2>Value differences</h2><span class="muted">${conflicts.length?'Review before trading':'Sources agree'}</span></div>${conflicts.length?`<div class="table-wrap"><table><thead><tr><th>Item</th><th>Google Sheet</th><th>Vaulted Values X</th></tr></thead><tbody>${conflicts.map(conflict=>`<tr><td><b>${esc(conflict.name)}</b><small>${esc(conflict.field||'value')}</small></td><td>${esc(money(conflict.googleSheet))}</td><td>${esc(money(conflict.vaultedValuesX))}</td></tr>`).join('')}</tbody></table></div><p class="panel-note">The value list currently uses the reconciled published snapshot. These rows make source differences visible instead of hiding them.</p>`:'<p class="muted">No value differences were reported by the latest source audit.</p>'}</section>`;}
function updatesPage(){const s=data.sync||{};const next=s.lastChecked?new Date(new Date(s.lastChecked).getTime()+7200000):null;return `<div class="page-head"><div><p class="eyebrow">DATA HEALTH</p><h1>Recent Changes</h1><p class="muted">Latest app change: the Settings page was removed to keep Haze Atlas simpler. Value changes and source checks are listed below.</p></div><button class="primary" id="refresh2">↻ Reload snapshot</button></div><section class="panel"><h2>Sync status: ${esc(s.status||'Ready')}</h2><div class="update-row"><span class="update-dot"></span><div><b>${esc(data.lastRefresh||'Bundled data loaded')}</b><small>Last checked: ${s.lastChecked?new Date(s.lastChecked).toLocaleString():'Not checked yet'} · Last updated: ${s.lastUpdated?new Date(s.lastUpdated).toLocaleString():'Bundled data'} · Next check: ${next?next.toLocaleString():'After startup'}</small></div></div></section>`;}
function tutorialPage(){const rows=(data.sheets.Tutorial||[]).filter(r=>r.some(Boolean));return `<div class="page-head compact"><div><p class="eyebrow">KNOW BEFORE YOU TRADE</p><h1>Trading tutorial</h1><p class="muted">Guidance imported from the source sheet, plus quick tool tips.</p></div></div><div class="tutorial-grid"><section class="panel"><h2>Read the value list</h2><p>Value is a guide, not a guarantee. Demand shows how easy an item may be to trade; rarity and PvP/PvE usefulness help provide context.</p><h3>Calculator</h3><p>Add both offers, then use the percentage and outcome as a starting point—not the only factor in a deal.</p><h3>Important warning</h3><p>Never trade based only on someone else's claim. Check the current source and all item details before confirming.</p></section><section class="panel"><h2>Source tutorial content</h2><div class="source-rows">${rows.map(r=>`<p>${r.filter(Boolean).map(esc).join(' — ')}</p>`).join('')}</div></section></div>`;}
function masteryPage(){const s=mastery.summary||{};return `<div class="page-head compact"><div><p class="eyebrow">EXACT PROGRESSION DATA</p><h1>Mastery XP calculator</h1><p class="muted">Exact UI XP from the 0–500 table, with grind estimates aligned to official Mastery System ratios.</p></div></div><div class="stats"><div class="stat cyan"><div><small>0 → 500 UI XP</small><strong>${money(s.totalUiXp0To500||0)}</strong></div><span>✧</span></div><div class="stat gold"><div><small>M1 HITS WITH CARRY</small><strong>${money(s.totalM1HitsIfXpCarriesOver||0)}</strong></div><span>◈</span></div><div class="stat"><div><small>FINAL LEVEL XP</small><strong>${money(s.finalLevelUiXp||0)}</strong></div><span>↑</span></div></div><section class="panel mastery-panel"><div class="panel-title"><h2>Plan your mastery</h2><span class="muted">M1 = 3 UI XP · Skill = 30 · NPC = 60 · Boss = 300 · Superboss = 4,500</span></div><div class="settings mastery-inputs"><label>Current mastery<input id="masteryCurrent" type="number" min="0" max="500" value="0"></label><label>Target mastery<input id="masteryTarget" type="number" min="0" max="500" value="500"></label></div><div class="details"><div><span>UI XP needed</span><b id="masteryUiXp">—</b></div><div><span>M1 hits needed</span><b id="masteryHits">—</b></div><div><span>Skill uses</span><b id="masterySkills">—</b></div><div><span>NPC kills</span><b id="masteryNpcs">—</b></div><div><span>Boss kills</span><b id="masteryBosses">—</b></div><div><span>Superboss kills</span><b id="masterySupers">—</b></div><div><span>Internal EXP</span><b id="masteryInternal">—</b></div><div><span>Next-level UI XP</span><b id="masteryNext">—</b></div></div><p class="detail-note" id="masteryNote">Choose a current and target mastery to calculate the exact total.</p></section><section class="panel"><h2>How the estimate works</h2><p>It sums each exact UI XP row between your selected mastery levels. Hit counts divide the total (carry-over), using the same 10× UI scaling as the official internal EXP formula on Trello.</p><p class="muted">Sources: Exact Mastery UI XP Table (0–500) + official Mastery System card.</p></section>`;}
function updateMasteryCalc(){if(!mastery.levels?.length||!$('#masteryCurrent'))return;let a=Math.max(0,Math.min(500,Number($('#masteryCurrent').value)||0)),b=Math.max(0,Math.min(500,Number($('#masteryTarget').value)||0));if(b<a){[a,b]=[b,a];$('#masteryCurrent').value=a;$('#masteryTarget').value=b}const rows=mastery.levels.slice(a,b),xp=rows.reduce((n,x)=>n+x.uiXpToNext,0),internal=rows.reduce((n,x)=>n+x.internalExpToNext,0),next=mastery.levels[a],ceil=n=>Math.ceil(xp/n);$('#masteryUiXp').textContent=money(xp);$('#masteryHits').textContent=money(ceil(3));if($('#masterySkills')){$('#masterySkills').textContent=money(ceil(30));$('#masteryNpcs').textContent=money(ceil(60));$('#masteryBosses').textContent=money(ceil(300));$('#masterySupers').textContent=money(ceil(4500));}$('#masteryInternal').textContent=money(internal);$('#masteryNext').textContent=next?money(next.uiXpToNext):'Complete';$('#masteryNote').textContent=a===b?'You are already at the selected target.':`Mastery ${a} → ${b}: ${money(xp)} exact UI XP. Estimates assume leftover XP carries forward.`;}
function settingsPage(){return `<div class="page-head compact"><div><p class="eyebrow">PREFERENCES</p><h1>Settings</h1><p class="muted">These settings remain on this device only.</p></div></div><section class="panel settings"><label>Theme<select id="theme"><option value="dark">Dark ocean</option><option value="light">Light</option></select></label><label>Interface density<select id="density"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><div class="footer-notes settings-notes"><div class="footer-note"><small>Affiliation</small><span>Fan-made · not affiliated with Roblox or Haze Studios</span></div><div class="footer-note"><small>Values</small><span>Community value list</span></div><div class="footer-note"><small>Gameplay</small><span>Official Trello</span></div></div><div class="settings-links"><a class="secondary" href="https://www.roblox.com/games/6918802270/Haze-Seas" target="_blank" rel="noopener">Play Haze Seas</a><a class="secondary" href="https://discord.gg/hazeseas" target="_blank" rel="noopener">Official Discord</a><a class="secondary" href="https://trello.com/b/nn8bpTB0/haze-seas-official-trello" target="_blank" rel="noopener">Official Trello</a></div><button class="secondary" id="clearData">Clear local preferences</button></section>`;}
const RD_CODE_IMAGES=[
  './item-thumbnails/fruits-dragon.webp',
  './item-thumbnails/fruits-dough.webp',
  './item-thumbnails/fruits-buddha.webp',
  './item-thumbnails/fruits-leopard.webp',
  './item-thumbnails/fruits-phoenix.webp',
  './item-thumbnails/fruits-ice.webp',
  './item-thumbnails/swords-enma.webp',
  './item-thumbnails/swords-ace.webp',
  './item-thumbnails/swords-dark-blade.webp',
  './item-thumbnails/accessories-dragon-horns.webp',
  './item-thumbnails/accessories-ice-crown.webp',
  './item-thumbnails/gamepasses-vip.webp'
];
function rdCodeArt(index){return RD_CODE_IMAGES[index % RD_CODE_IMAGES.length];}
function parseOfficialCodes(){const entry=content.entries.find(x=>/codes/i.test(cleanDisplayName(x.name))&&x.category==='Game Info');if(!entry)return [];const rows=[];for(const raw of String(entry.description||'').split('\n')){const line=raw.replace(/[‌﻿]/g,'').trim();const match=line.match(/^[-*]\s*\*\*(.+?)\*\*\s*(?:[:\-]\s*)?(.*)$/);if(!match)continue;const code=match[1].trim().replace(/:$/,'');const reward=match[2].replace(/^[-:]\s*/,'').replace(/[_\\]/g,'').replace(/\s+/g,' ').trim()||'Reward not specified';rows.push({code,reward,source:entry.source});}return rows;}
function codesPage(){const codes=parseOfficialCodes(),entry=content.entries.find(x=>/codes/i.test(cleanDisplayName(x.name))&&x.category==='Game Info');return `<div class="page-head compact"><div><p class="eyebrow">OFFICIAL REDEEMABLES</p><h1>Codes</h1><p class="muted">Pulled from the official Haze Seas Trello Codes card. Codes expire—redeem in-game via Menu → gift box.</p></div>${entry?.source?`<a class="secondary" href="${esc(entry.source)}" target="_blank" rel="noopener">View on Trello ↗</a>`:''}</div><section class="panel codes-howto"><div class="panel-title"><h2>How to redeem</h2><span class="muted">In-game</span></div><ol class="codes-steps"><li>Launch <strong>Haze Seas</strong> on Roblox</li><li>Open the <strong>Menu</strong> on the left side of the screen</li><li>Tap the red <strong>gift box</strong> icon</li><li>Enter a code and press <strong>Redeem</strong></li></ol></section><div class="codes-grid">${codes.map((c,i)=>`<article class="code-tile code-tile-full"><div class="code-tile-header"><img src="${rdCodeArt(i)}" alt="" class="code-tile-art" loading="lazy"><div class="code-tile-body"><code class="code-tile-code">${esc(c.code)}</code><p class="code-tile-reward">${esc(c.reward)}</p></div></div><button type="button" class="code-tile-copy code-card-copy" data-copy-code="${esc(c.code)}" aria-label="Copy code ${esc(c.code)}">Copy</button></article>`).join('')||'<div class="empty">No codes are currently listed on the official Trello card.</div>'}</div><p class="panel-note codes-footnote">Source: official Trello · last checked ${entry?.lastChecked?new Date(entry.lastChecked).toLocaleDateString():'—'}. Always verify against Trello if a code fails.</p>`;}
function systemsPage(){const systems=content.entries.filter(x=>!x.aliasOf&&!x.archived&&x.category==='Game Info'&&!/^\u1cbc?$/.test(cleanDisplayName(x.name))).sort((a,b)=>cleanDisplayName(a.name).localeCompare(cleanDisplayName(b.name)));return `<div class="page-head compact"><div><p class="eyebrow">OFFICIAL GAME SYSTEMS</p><h1>Game systems</h1><p class="muted">Mastery, materials, bounty, chests, controls, and more—straight from official Trello Game Info cards.</p></div></div><div class="item-grid content-grid">${systems.map(x=>`<article class="item-card content-card" data-content="${esc(x.id)}"><div class="card-top">${contentArt(x)}<span class="pill muted">SYSTEM</span></div><h3>${esc(cleanDisplayName(x.name)||x.name)}</h3><p class="muted">${esc(cleanText(x.description).slice(0,120))}</p></article>`).join('')||'<div class="empty">No Game Info cards are available yet.</div>'}</div>`;}
function detailMedia(item){return `<img class="detail-art" src="./${esc(artPath(item))}" alt="${esc(item.name)} image">`;}
let powerMediaManifest;
function powerGifs(item){return `<section class="panel power-media"><p class="eyebrow">OFFICIAL POWER VIDEOS</p><button class="secondary" data-power-name="${esc(item.name)}" onclick="loadPowerMedia(this, this.dataset.powerName)">Load official power previews</button></section>`;}
async function loadPowerMedia(button,name){button.disabled=true;button.textContent='Loading previews…';try{powerMediaManifest??=await fetch('./power-media/manifest.json', { cache: 'no-store' }).then(r=>{if(!r.ok)throw new Error('Manifest unavailable');return r.json()});const clips=powerMediaManifest.items.filter(x=>x.status!=='error'&&x.cards.some(card=>card.toLowerCase()===String(name).toLowerCase()));if(!clips.length){button.closest('.power-media').innerHTML='<p class="muted">No official power preview is available for this record yet.</p>';return}button.closest('.power-media').innerHTML=`<p class="eyebrow">OFFICIAL POWER VIDEOS · ${clips.length}</p><div class="power-video-grid">${clips.map((clip,i)=>`<video class="power-video" controls preload="none" poster="./trello-images/item-placeholder.webp" aria-label="${esc(name)} power preview ${i+1}"><source src="./power-media/${esc(clip.file)}" type="video/webm"></video>`).join('')}</div>`}catch(error){button.disabled=false;button.textContent='Try loading official power previews again';console.error('Power media load failed',error)}}
function transformationGuide(item){if(item.id!=='fruits-dragon')return '';return `<section class="panel dragon-guide"><p class="eyebrow">DRAGON TRANSFORMATIONS</p><h2>How to unlock each form</h2><div class="details"><div><span>Full Form</span><b>Reach 125 Dragon Mastery, then use E: Transformation.</b></div><div><span>Base Hybrid Mode</span><b>Reach 150 Dragon Mastery, then use N: Hybrid Mode.</b></div><div><span>Dragon Hybrid Form skills</span><b>On Land of the Gods, defeat 1,000 NPCs and blow a Dragon Trumpet; defeat Dragon Hybrid, take its guaranteed Dragon Heart to the Sea 3 Poneglyph, and repeat for each skill.</b></div></div><a class="secondary guide-source" href="https://trello.com/c/qV4qI0wT/113-dragon" target="_blank" rel="noopener">View official Dragon Trello</a></section>`;}
function swordGuide(item){if(item.category.toLowerCase()!=='swords')return '';const direct=trello.items[item.id],norm=s=>String(s||'').toLowerCase().replace(/\([^)]*\)/g,'').replace(/(?:v|version)\s*\d+/g,'').replace(/[^a-z0-9]/g,''),linked=content.entries.find(x=>x.valueId===item.id)||content.entries.find(x=>norm(x.name)===norm(item.name)),record=direct?.description?direct:linked,description=record?.description,url=record?.url||direct?.url||linked?.source;if(!description)return `<section class="panel sword-guide"><p class="eyebrow">HOW TO GET THIS SWORD</p><p class="muted">No official obtainment route is documented in the current Trello record.</p></section>`;return `<section class="panel sword-guide"><p class="eyebrow">HOW TO GET THIS SWORD</p><div class="structured-description">${formatDescription(description)}</div>${url?`<a class="secondary guide-source" href="${esc(url)}" target="_blank" rel="noopener">View official Trello</a>`:''}</section>`;}
function detail(item){rememberItem(item);const dialog=$('#detailDialog'),nearby=nearbyItems(item),previous=recentItems.filter(x=>x.id===item.id).slice(1,4);const nearbyHtml=nearby.length?`<section class="panel market-profile"><div class="panel-title"><h2>Nearby current values</h2><span>Within 20%</span></div><div class="market-list">${nearby.map(x=>`<button data-item="${esc(x.id)}"><span><b>${esc(x.name)}</b><small>${esc(x.demand||'—')} demand</small></span><strong>${esc(x.valueText||'Unlisted')}</strong><em>${x.diff>=0?'+':''}${x.diff.toFixed(1)}%</em></button>`).join('')}</div></section>`:'<section class="panel market-profile"><div class="panel-title"><h2>Nearby current values</h2><span>No listed matches yet</span></div></section>';const historyHtml=`<section class="panel market-profile"><div class="panel-title"><h2>Your value snapshots</h2><span>Saved on this device</span></div><p class="detail-note">This records the value when you open this item. It is not a claimed market-history chart.</p><div class="market-list">${previous.map(x=>`<div><span><b>${esc(x.valueText)}</b><small>${new Date(x.seenAt).toLocaleString()}</small></span><strong>${esc(x.demand)}</strong></div>`).join('')||'<p class="muted">Open this item again after a data update to build your own value snapshots.</p>'}</div></section>`;$('#detail').innerHTML=`<button class="close dialog-close">×</button><div class="detail-head">${detailMedia(item)}<div><p class="eyebrow">ITEM MARKET PROFILE · ${esc(item.category)}</p><h1>${esc(item.name)}</h1><p>${esc(item.rarity||'Unknown')} · ${status(item)}</p></div></div><div class="detail-value">${esc(item.valueText||'Unlisted')}<small>Current trading value</small></div><div class="details"><div><span>Demand</span><b>${esc(item.demand||'—')}</b></div><div><span>Value in dragons</span><b>${esc(item.dragons||'—')}</b></div>${item.robux?`<div><span>Robux cost</span><b>${esc(item.robux)}</b></div>`:''}<div><span>PvP</span><b>${esc(item.pvp||'—')}</b></div><div><span>PvE</span><b>${esc(item.pve||'—')}</b></div></div>${accessoryStatsPanel(item)}${nearbyHtml}${historyHtml}${transformationGuide(item)}${swordGuide(item)}${powerGifs(item)}<p class="detail-note">Current values, demand, and rarity are reconciled with Vaulted Values X. Dragon equivalents, Robux costs, and PvP/PvE notes come from the published Haze Seas spreadsheet.</p><div class="detail-actions"><button class="primary" data-fav="${item.id}">${isFav(item.id)?'♥ Favorited':'♡ Add favorite'}</button><button class="secondary" data-add-trade="${item.id}">Add to trade</button><button class="secondary" onclick="openIdeas('${esc(item.id)}')">Find trade ideas</button><button class="secondary" data-compare="${item.id}">Compare</button><button class="secondary" id="copyVal">Copy value</button></div>`;dialog.showModal();$('.dialog-close').onclick=()=>dialog.close();$('#copyVal').onclick=()=>navigator.clipboard.writeText(item.valueText||'Unlisted').then(()=>toast('Value copied'));bindDynamic();}
function cleanText(s=''){return s.replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/[‌﻿]/g,'').replace(/\n{3,}/g,'\n\n').trim();}
function descriptionInline(s=''){return esc(s.trim()).replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/_([^_]+)_/g,'<em>$1</em>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function formatDescription(s=''){const lines=cleanText(s).split('\n').map(x=>x.trim()),out=[];let paragraph=[],list=[],quote=[],ordered=false;const flush=()=>{if(quote.length){out.push(`<blockquote>${quote.map(x=>`<p>${descriptionInline(x)}</p>`).join('')}</blockquote>`);quote=[]}if(list.length){out.push(`<${ordered?'ol':'ul'}>${list.map(x=>`<li>${descriptionInline(x)}</li>`).join('')}</${ordered?'ol':'ul'}>`);list=[]}if(paragraph.length){out.push(`<p>${paragraph.map(descriptionInline).join('<br>')}</p>`);paragraph=[]}};for(const line of lines){if(!line){flush();continue}if(/^---+$/.test(line)){flush();out.push('<hr>');continue}const boldHeading=line.match(/^\*\*(.+?)\*\*(.*)$/),heading=line.match(/^#{1,6}\s+(.+)$/);if(boldHeading||heading){flush();const title=boldHeading?boldHeading[1]+boldHeading[2]:heading[1];out.push(`<h3>${descriptionInline(title)}</h3>`);continue}if(/^>\s?/.test(line)){if(paragraph.length||list.length)flush();quote.push(line.replace(/^>\s?/,''));continue}const bullet=line.match(/^[-*]\s+(.+)/),numbered=line.match(/^\d+\.\s+(.+)/);if(bullet||numbered){if(paragraph.length||quote.length)flush();const nextOrdered=Boolean(numbered);if(list.length&&ordered!==nextOrdered)flush();ordered=nextOrdered;list.push((bullet||numbered)[1]);continue}if(/^(?:[A-Z][\w &.-]{2,60}):\s*$/.test(line)){flush();out.push(`<h3>${descriptionInline(line.slice(0,-1))}</h3>`);continue}if(list.length||quote.length)flush();paragraph.push(line)}flush();return out.join('')||'<p>No public description is available yet.</p>';}
function contentArt(x){const valueItem=x.valueId&&data.items.find(v=>v.id===x.valueId),nativeMissing=Boolean(window.Capacitor?.isNativePlatform?.())&&/^(trello-content-images|trello-images|power-media|power-posters)\//.test(x.image||'');if(x.image&&!nativeMissing)return `<img class="item-art" src="./${esc(x.image)}" alt="${x.generatedImage?'Haze encyclopedia artwork for ':'Official Haze Seas art for '}${esc(x.name)}">`;return valueItem?art(valueItem):`<div class="item-art content-art-empty" aria-hidden="true">✦</div>`;}
function fishPictures(x){if(x.category!=='Fishing')return '';let title='',pictures=[];for(const line of (x.description||'').split('\n')){const heading=line.match(/^#{1,6}\s+(.+)$/);if(heading){title=heading[1].replace(/[*_`]/g,'').trim();continue}const image=line.match(/!\[[^\]]*\]\((https?:\/\/[^)\s]+)[^)]*\)/);if(image)pictures.push({title:title||x.name,url:image[1]})}if(!pictures.length)return '';return `<section class="fish-gallery"><p class="eyebrow">OFFICIAL FISH PICTURES · ${pictures.length}</p><div>${pictures.map(pic=>`<figure><img loading="lazy" referrerpolicy="no-referrer" src="${esc(pic.url)}" alt="${esc(pic.title)}"><figcaption>${esc(pic.title)}</figcaption></figure>`).join('')}</div></section>`;}
function titleRecords(entry){const groups=new Set(['Level','Collector','Unlock','Money','Bounty','Kills','Death','PVP','Fishing','Playtime','Gems','Trade','Event','Achievement','Regular','Shrine','Role']),rows=[],seen=new Set();let group='Other';for(const original of String(entry.description||'').split('\n')){let line=original.replace(/[‌﻿]/g,'').trim();if(!line)continue;const heading=line.match(/^#{2,4}\s+(?:\*\*)?(.+?)(?:\*\*)?:?$/);if(heading){const name=heading[1].replace(/\*\*/g,'').replace(/\[|\]|\([^)]*\)/g,'').replace(/:$/,'').trim();if(groups.has(name))group=name;continue}const section=line.match(/^\*\*(.+?):\*\*$/);if(section&&groups.has(section[1].trim())){group=section[1].trim();continue}line=line.replace(/^-\s*/,'');let match=line.match(/^Title\s+["']?\*{0,2}(.+?)\*{0,2}["']?\s*[-:—]\s*(.+)$/i)||line.match(/^\*\*(.+?):\*\*\s*(.+)$/)||line.match(/^([^:]{2,70}):\s*(.+)$/);if(!match)continue;const name=match[1].replace(/^Title\s+/i,'').replace(/["*]/g,'').trim(),how=match[2].replace(/\*\*/g,'').trim();if(!name||!how||/^(total|new titles)$/i.test(name))continue;const key=`${name}|${how}`;if(!seen.has(key)){seen.add(key);rows.push({name,how,group})}}return rows}
function titlesDetail(entry){const dialog=$('#detailDialog'),records=titleRecords(entry),groups=['All',...new Set(records.map(x=>x.group))];$('#detail').innerHTML=`<button class="close dialog-close">×</button><div class="title-guide-head"><p class="eyebrow">OFFICIAL TITLE GUIDE</p><h1>Titles — how to unlock them</h1><p class="muted">Search a title, then read the exact requirement in one line. Requirements are from the official Haze Seas Trello.</p><input id="titleGuideSearch" placeholder="Search titles or requirements…" aria-label="Search title requirements"></div><div class="title-guide-filters">${groups.map((group,index)=>`<button type="button" class="${index===0?'active':''}" data-title-group="${esc(group)}">${esc(group)}</button>`).join('')}</div><p id="titleGuideCount" class="muted"></p><div id="titleGuideGrid" class="title-unlock-grid"></div><a class="secondary guide-source" href="${esc(entry.source)}" target="_blank" rel="noopener">View official Titles card ↗</a>`;let active='All';const draw=()=>{const query=$('#titleGuideSearch').value.toLowerCase(),show=records.filter(x=>(active==='All'||x.group===active)&&`${x.name} ${x.how}`.toLowerCase().includes(query));$('#titleGuideCount').textContent=`${show.length} title${show.length===1?'':'s'} shown`;$('#titleGuideGrid').innerHTML=show.map(x=>`<article class="title-unlock-card"><small>${esc(x.group)}</small><h3>${esc(x.name)}</h3><p><b>How to get it:</b> ${esc(x.how)}</p></article>`).join('')||'<p class="empty">No title matches that search.</p>'};$('#titleGuideSearch').oninput=draw;$$('[data-title-group]').forEach(button=>button.onclick=()=>{active=button.dataset.titleGroup;$$('[data-title-group]').forEach(x=>x.classList.toggle('active',x===button));draw()});draw();dialog.showModal();$('.dialog-close').onclick=()=>dialog.close();}
function contentDetail(x){if(cleanDisplayName(x.name)==='Titles')return titlesDetail(x);const dialog=$('#detailDialog'),nativeApp=Boolean(window.Capacitor?.isNativePlatform?.()),photos=nativeApp?[]:(x.images||[]),gifs=nativeApp?[]:(x.gifs||[]),displayName=cleanDisplayName(x.name)||x.name,gallery=[...photos,...gifs].length?`<section class="power-previews"><p class="eyebrow">${/wandering merchant/i.test(displayName)?'SPAWN LOCATIONS':gifs.length?'OFFICIAL POWER PREVIEWS':'OFFICIAL IMAGES'}</p><div>${[...photos,...gifs].map((img,i)=>`<img class="power-gif" src="./${esc(img)}" alt="${esc(displayName)} ${i+1}">`).join('')}</div></section>`:'';$('#detail').innerHTML=`<button class="close dialog-close">×</button><div class="detail-head">${contentArt(x)}<div><p class="eyebrow">${esc(x.category)}</p><h1>${x.released?'':'🚧 '}${esc(displayName)}</h1></div></div><div class="content-description structured-description">${formatDescription(x.description)}</div>${fishPictures(x)}${gallery}<div class="details"><div><span>Category</span><b>${esc(x.category)}</b></div><div><span>Release</span><b>${x.released?'Released':'Unreleased'}</b></div><div><span>Last checked</span><b>${x.lastChecked?new Date(x.lastChecked).toLocaleDateString():'—'}</b></div></div>${x.source?`<a class="secondary guide-source" href="${esc(x.source)}" target="_blank" rel="noopener">View official Trello ↗</a>`:''}`;dialog.showModal();$('.dialog-close').onclick=()=>dialog.close();}
